from datetime import datetime

from app.ai.agents.base_agent import BaseAgent
from app.ai.orchestrator.state import LexIntelState
from app.ai.logging.logger import AILogger

logger = AILogger("agent.report_explainability")

_REPORT_DISCLAIMER = (
    "⚠️ AI GENERATED REPORT — FOR INFORMATIONAL PURPOSES ONLY\n"
    "This report was generated by LexIntel AI and does NOT constitute legal advice. "
    "All predictions are probabilistic estimates. "
    "Consult a qualified lawyer before taking any legal action."
)


class ReportExplainabilityAgent(BaseAgent):
    """
    Phase 3B — Agent 4: Report & Explainability

    Synthesizes all Phase 3A + 3B outputs into a single comprehensive,
    explainable case intelligence report readable by citizens, lawyers, and judges.
    Every major conclusion includes evidence used, legal references,
    similar judgments, and a full reasoning chain.
    Never overwrites prior state fields.
    """

    agent_name = "report_explainability"
    prompt_name = "report_explainability"

    async def execute(self, state: LexIntelState) -> LexIntelState:
        doc_intel = state.get("document_intelligence") or {}
        legal_research = state.get("legal_research") or {}
        similar_cases = state.get("similar_cases") or []
        evidence_analysis = state.get("evidence_analysis") or {}
        evidence_timeline = state.get("evidence_timeline") or []
        missing_hints = state.get("missing_evidence_hints") or []
        outcome = state.get("outcome_prediction") or {}
        strategy = state.get("legal_strategy") or {}
        drafts = state.get("legal_drafts") or []

        case_name = state.get("case_name") or "Untitled Case"

        # Build compact context — guard every value against None
        doc_intel_summary = doc_intel.get("summary") or ""
        parties = ", ".join(doc_intel.get("parties") or [])
        legal_summary = legal_research.get("research_summary") or ""
        applicable_acts = ", ".join(legal_research.get("applicable_acts") or [])

        similar_cases_summary = "; ".join(
            f"{c.get('case_name','?')} ({c.get('year','')}) → {c.get('verdict','?')}"
            for c in (similar_cases or [])[:5]
        )

        evidence_summary = evidence_analysis.get("analysis_summary") or ""
        timeline_summary = "; ".join(
            (e.get("event_description") or "") for e in (evidence_timeline or [])[:6]
        )
        missing_list = "; ".join(missing_hints[:5])

        prediction_summary = (
            f"Probability: {outcome.get('probability_of_success') or 'N/A'}, "
            f"Strength: {outcome.get('case_strength_score') or 'N/A'}, "
            f"Confidence: {outcome.get('confidence_level') or 'N/A'}, "
            f"Risk: {outcome.get('risk_level') or 'N/A'}"
        )

        strategy_names = "; ".join(
            (s.get("name") or "") for s in (strategy.get("strategies") or [])[:3]
        )
        strategy_summary = (
            f"Strategies: {strategy_names}. "
            f"Immediate steps: {'; '.join((strategy.get('immediate_next_steps') or [])[:3])}"
        )

        drafts_summary = ", ".join(
            (d.get("document_type") or "Unknown") for d in (drafts or [])
        ) or "None"

        prompt = self.get_prompt()
        response = await self.invoke_llm(
            prompt.system,
            prompt.render_user(
                case_name=case_name,
                doc_intel_summary=doc_intel_summary[:600],
                parties=parties[:300],
                legal_summary=legal_summary[:600],
                applicable_acts=applicable_acts[:400],
                similar_cases_summary=similar_cases_summary[:500],
                evidence_summary=evidence_summary[:500],
                timeline_summary=timeline_summary[:400],
                missing_list=missing_list[:300],
                prediction_summary=prediction_summary[:300],
                strategy_summary=strategy_summary[:400],
                drafts_summary=drafts_summary[:200],
            ),
        )
        parsed = self.parse_json_response(response.content)

        parsed["disclaimer"] = _REPORT_DISCLAIMER
        parsed["ai_generated"] = True
        parsed["generated_at"] = datetime.utcnow().isoformat()
        parsed["case_name"] = case_name

        # Attach full structured data for frontend rendering
        parsed["full_timeline"] = evidence_timeline
        parsed["full_similar_cases"] = similar_cases
        parsed["full_evidence_items"] = state.get("evidence_items") or []
        parsed["full_legal_provisions"] = (legal_research.get("provisions") or [])

        state["case_report"] = parsed
        # Keep legacy field in sync
        state["final_report"] = parsed.get("executive_summary", "")

        logger.info(
            "Report generation complete",
            explainability_items=len(parsed.get("explainability") or []),
            confidence=parsed.get("ai_confidence_overall"),
        )
        return state
